import React, { useState } from 'react';
import './App.css';
import { BrowserRouter as Router, Route, Routes, NavLink } from 'react-router-dom'; // Importando NavLink
import ClienteList from './components/Clientes/ClienteList';
import CreateCliente from './components/Clientes/CreateCliente';
import ProjetoList from './components/Projetos/ProjetoList';
import CreateProjeto from './components/Projetos/CreateProjeto';
import AtividadeList from './components/Atividades/AtividadeList';
import CreateAtividade from './components/Atividades/CreateAtividade';

const App = () => {
  const [clientes, setClientes] = useState([]);
  const [selectedClienteId, setSelectedClienteId] = useState(null);
  const [selectedProjetoId, setSelectedProjetoId] = useState(null);

  return (
    <Router>
      <div className="container">
        <h1>Gestão de Clientes</h1>

        {/* Navbar de navegação */}
        <nav className="navbar">
          <NavLink to="/clientes" className="nav-link" activeClassName="active">
            Clientes
          </NavLink>
          <NavLink to="/projetos" className="nav-link" activeClassName="active">
            Projetos
          </NavLink>
          <NavLink to="/atividades" className="nav-link" activeClassName="active">
            Atividades
          </NavLink>
        </nav>

        {/* Definição das rotas */}
        <Routes>
          {/* Rota de Clientes */}
          <Route path="/clientes" element={
            <>
              <CreateCliente onCreate={setClientes} />
              <ClienteList clientes={clientes} setSelectedClienteId={setSelectedClienteId} />
            </>
          } />

          {/* Rota de Projetos */}
          <Route path="/projetos" element={
            <ProjetoList clienteId={selectedClienteId} setSelectedProjetoId={setSelectedProjetoId} />
          } />

          {/* Rota de Atividades */}
          <Route path="/atividades" element={
            <AtividadeList clienteId={selectedClienteId} projetoId={selectedProjetoId} />
          } />

          {/* Rota para a criação de projetos e atividades */}
          <Route path="/projeto/criar" element={<CreateProjeto clienteId={selectedClienteId} />} />
          <Route path="/atividade/criar" element={<CreateAtividade clienteId={selectedClienteId} projetoId={selectedProjetoId} />} />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
